            if not chunk:
                raise IOError("connection closed")
            self.buf += chunk
        line, self.buf = self.buf.split(b"\r\n", 1)
        return line

    def _exact(self, n):
        while len(self.buf) < n + 2:
            chunk = self.sock.recv(65536)
            if not chunk:
                raise IOError("connection closed")
            self.buf += chunk
        data, self.buf = self.buf[:n], self.buf[n + 2:]
        return data

    def _read(self):
        line = self._line()
        kind, rest = line[:1], line[1:]
        if kind == b"+":
            return rest.decode()
        if kind == b"-":
            raise RuntimeError(rest.decode())
        if kind == b":":
            return int(rest)
        if kind == b"$":
            n = int(rest)
            return None if n == -1 else self._exact(n).decode()
        if kind == b"*":
            n = int(rest)
            return None if n == -1 else [self._read() for _ in range(n)]
        raise RuntimeError("bad RESP: %r" % line)

    def cmd(self, *args):
        out = [b"*%d\r\n" % len(args)]
        for a in args:
            b = a.encode() if isinstance(a, str) else a
            out.append(b"$%d\r\n%s\r\n" % (len(b), b))
        self.sock.sendall(b"".join(out))
        return self._read()


def score(raw):
    f = float(raw)
    return int(f) if f.is_integer() else f


def main():
    r = Resp(HOST, PORT)
    r.cmd("SELECT", str(DB))

    keys = []
    cursor = "0"
    while True:
        cursor, batch = r.cmd("SCAN", cursor, "COUNT", "1000")
        keys.extend(batch)
        if cursor == "0":
            break

    entries = []
    for name in sorted(keys):
        ktype = r.cmd("TYPE", name)
        if ktype == "string":
            value = r.cmd("GET", name)
        elif ktype == "hash":
            flat = r.cmd("HGETALL", name)
            pairs = dict(zip(flat[0::2], flat[1::2]))
            value = {k: pairs[k] for k in sorted(pairs)}
        elif ktype == "list":
            value = r.cmd("LRANGE", name, "0", "-1")
        elif ktype == "set":
            value = sorted(r.cmd("SMEMBERS", name))
        elif ktype == "zset":
            flat = r.cmd("ZRANGE", name, "0", "-1", "WITHSCORES")
            members = list(zip(flat[0::2], flat[1::2]))
            value = [{"member": m, "score": score(s)}
                     for m, s in sorted(members, key=lambda p: p[0])]
        elif ktype == "stream":
            value = [{"id": sid, "fields": dict(zip(f[0::2], f[1::2]))}
                     for sid, f in r.cmd("XRANGE", name, "-", "+")]
        else:
            raise RuntimeError("unsupported type %s for key %s" % (ktype, name))
        entries.append({"name": name, "type": ktype, "value": value})

    doc = {"db": DB, "keys": entries}
    with open("/results/recovered.json", "w", encoding="utf-8") as fh:
        json.dump(doc, fh, ensure_ascii=False, indent=2)
        fh.write("\n")
    print("wrote %d keys" % len(entries))


if __name__ == "__main__":
    main()

